<script setup lang="ts">
import type {ProductQuery} from '~/shared/types'
const props=defineProps<{categorySlug?:string;collectionSlug?:string;onlyNew?:boolean}>()
const route=useRoute(),router=useRouter(),api=useApi(),search=ref(String(route.query.q||''))
const {data:categories}=await useAsyncData('categories',()=>api.categories())
const category=computed(()=>categories.value?.find(c=>c.slug===props.categorySlug))
if(props.categorySlug&&!category.value)throw createError({statusCode:404,statusMessage:'Категория не найдена'})
const {data:collections}=await useAsyncData('collections',()=>api.collections())
const collection=computed(()=>collections.value?.find(c=>c.slug===props.collectionSlug))
if(props.collectionSlug&&!collection.value)throw createError({statusCode:404,statusMessage:'Коллекция не найдена'})
const title=computed(()=>category.value?.name||collection.value?.name||(props.onlyNew?'Новинки':'Все находки'))
const description=computed(()=>category.value?.description||collection.value?.description||(props.onlyNew?'Новые вещи, которые уже стали частью нашей истории. Новинки за последние 30 дней.':'Одежда, небольшие артефакты и вещи с характером. Что станет частью вашей истории?'))
const query=computed<ProductQuery>(()=>({q:String(route.query.q||''),category:props.categorySlug||String(route.query.category||''),collection:props.collectionSlug||String(route.query.collection||''),available:String(route.query.available||''),sort:String(route.query.sort||'newest'),page:Number(route.query.page)||1,pageSize:9,new:props.onlyNew?'true':undefined,scenario:route.query.scenario?String(route.query.scenario):undefined}))
const {data,pending,error,refresh}=await useAsyncData(()=>`catalog-${route.path}-${JSON.stringify(query.value)}-${route.query.featured||''}`,()=>api.products({...query.value,featured:route.query.featured==='true'?'true':undefined}),{watch:[query]})
function update(values:Record<string,string|number|undefined>){router.push({path:route.path,query:{...route.query,page:undefined,...values}})}
function submit(){update({q:search.value.trim()||undefined})}
function reset(){search.value='';router.push({path:route.path,query:{}})}
watch(()=>route.query.q,v=>search.value=String(v||''))
useSeoMeta({title:()=>`${title.value} — Deadlock Family`,description:()=>description.value,ogTitle:()=>`${title.value} — Deadlock Family`})
</script>
<template><div class="container page"><div class="breadcrumbs"><NuxtLink to="/">Главная</NuxtLink><AppIcon name="chevron"/><span>{{title}}</span></div><div class="page-heading"><span class="eyebrow">КАТАЛОГ DEADLOCK FAMILY</span><h1>{{title}}</h1><p>{{description}}</p></div>
  <div class="catalog-layout"><aside class="catalog-sidebar" aria-label="Фильтры каталога"><p class="sidebar-label">Категории</p><NuxtLink to="/shop" class="category-filter" :class="{selected:!query.category}">Все находки <AppIcon name="arrow" :size="14"/></NuxtLink><NuxtLink v-for="c in categories" :key="c.id" :to="{path:`/shop/category/${c.slug}`,query:{q:query.q||undefined,sort:query.sort,available:query.available||undefined}}" class="category-filter" :class="{selected:query.category===c.slug}">{{c.name}}<AppIcon :name="c.icon" :size="16"/></NuxtLink><div class="sidebar-section"><p class="sidebar-label">Доступность</p><label class="check-label"><input type="checkbox" :checked="query.available==='true'" @change="update({available:($event.target as HTMLInputElement).checked?'true':undefined})">Только в наличии</label></div><div v-if="!collectionSlug" class="sidebar-section"><p class="sidebar-label">Коллекция</p><select class="filter-select" style="width:100%" aria-label="Фильтр по коллекции" :value="query.collection" @change="update({collection:($event.target as HTMLSelectElement).value||undefined})"><option value="">Все коллекции</option><option v-for="c in collections" :key="c.id" :value="c.slug">{{c.name}}</option></select></div><div class="sidebar-section"><button class="text-link" @click="reset"><AppIcon name="refresh" :size="14"/>Сбросить фильтры</button></div></aside>
  <div><form id="catalog-search" class="search-field" role="search" @submit.prevent="submit"><AppIcon name="search" :size="20"/><input v-model="search" aria-label="Поиск по каталогу" placeholder="Название, история или тайный знак…"><button type="submit" aria-label="Найти товары"><AppIcon name="arrow" :size="20"/></button></form><div class="catalog-toolbar"><span aria-live="polite">{{pending?'Ищем в архиве…':`Найдено товаров: ${data?.total||0}`}}</span><select class="filter-select" aria-label="Сортировка товаров" :value="query.sort" @change="update({sort:($event.target as HTMLSelectElement).value})"><option value="newest">Сначала новые</option><option value="price-asc">Цена: по возрастанию</option><option value="price-desc">Цена: по убыванию</option></select></div>
    <ApiState :pending="pending" :error="error" :empty="!data?.items.length" @retry="refresh()"><button class="btn" @click="reset">Сбросить фильтры</button></ApiState><div v-if="!pending&&!error" class="product-grid catalog-products"><ProductCard v-for="product in data?.items" :key="product.id" :product="product"/></div><nav v-if="data&&data.total>data.pageSize" class="pagination" aria-label="Страницы каталога"><button class="btn btn-small" :disabled="data.page<=1" @click="update({page:data.page-1})">Назад</button><span>{{data.page}} / {{Math.ceil(data.total/data.pageSize)}}</span><button class="btn btn-small" :disabled="data.page*data.pageSize>=data.total" @click="update({page:data.page+1})">Далее</button></nav>
  </div></div></div></template>
